{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "evidence for a volume- outcome relationship has been accumulated for various medical interventions including surgeries, dialysis, perinatal as well as intensive care. 4-14 Based on these findings, minimum volume standards have been introduced in numerous countries... Still, criticism remains. First, some studies have raised doubts about the underlying proposed volume- outcome relationship.",
      "reason": "The introduction describes the current state of knowledge (volume-outcome relationship, minimum volume standards) and uncertainties (criticism, differing cut-offs, discussed adverse effects)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Hence, despite the ongoing debate about the advantages and disadvantages of minimum volume standards, there has been no systematic review on the effects of minimum volume standards in hospitals. This systematic review aims to address this research gap.",
      "reason": "The need and importance of the review is explicitly explained as addressing a research gap."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "there is no reported systematic review collating evidence on the effects of minimum volume standards in hospitals. In Germany, a rapid review was published in 2012 by the Institute for Quality and Efficiency in Healthcare (IQWiG). In total, 10 studies were included in this report.",
      "reason": "The prior IQWiG rapid review is identified and cited, and the need for the current review relative to it is explained (methodological shortcomings, no systematic review since)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of policy/regulatory interventions (minimum volume standards), not a drug or biological intervention with a mechanism of action; the mechanism requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of a logic model being considered; the review evaluates effects of a regulatory standard rather than a complex multi-component intervention requiring a logic model, and no such model is reported."
    }
  ],
  "confidence": 88
}

